var cmd=root.querySelector('.trx2-c64-ready-cmd');
var cur=root.querySelector('.trx2-c64-ready-cur1');
var cur2=root.querySelector('.trx2-c64-ready-cur2');
var o=[root.querySelector('.trx2-c64-ready-o1'),root.querySelector('.trx2-c64-ready-o2'),root.querySelector('.trx2-c64-ready-t3')];
var text='LOAD"ZORK",8,1';
var out=['SEARCHING FOR ZORK','LOADING','READY.'];
var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if(rm){cmd.textContent=text;o[0].textContent=out[0];o[1].textContent=out[1];o[2].textContent=out[2];cur.classList.add('trx2-c64-ready-off');cur2.classList.add('trx2-c64-ready-on');return;}
var t=[];
function later(fn,ms){t.push(setTimeout(fn,ms));}
function run(){
  for(var j=0;j<t.length;j++){clearTimeout(t[j]);}
  t=[];
  cmd.textContent='';o[0].textContent='';o[1].textContent='';o[2].textContent='';
  cur.classList.remove('trx2-c64-ready-off');cur2.classList.remove('trx2-c64-ready-on');
  var i=0;
  function step(k){
    if(k<out.length){o[k].textContent=out[k];later(function(){step(k+1);},k===1?1500:700);return;}
    cur2.classList.add('trx2-c64-ready-on');
    later(run,2600);
  }
  function type(){
    if(i<text.length){cmd.textContent+=text.charAt(i++);later(type,60+Math.random()*70);return;}
    later(function(){cur.classList.add('trx2-c64-ready-off');step(0);},480);
  }
  type();
}
run();

var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var lines=root.querySelectorAll('.trx2-zx-list-line');
var t=[];
function later(f,m){t.push(setTimeout(f,m));}
function mark(i){for(var k=0;k<lines.length;k++){lines[k].classList.toggle('trx2-zx-list-cur',k===i);}}
if(rm){for(var a=0;a<lines.length;a++){lines[a].classList.add('trx2-zx-list-on');}mark(lines.length-1);return;}
function run(){
  for(var j=0;j<t.length;j++){clearTimeout(t[j]);}
  t=[];
  for(var b=0;b<lines.length;b++){lines[b].classList.remove('trx2-zx-list-on');lines[b].classList.remove('trx2-zx-list-cur');}
  function nxt(i){
    if(i<lines.length){lines[i].classList.add('trx2-zx-list-on');mark(i);later(function(){nxt(i+1);},250);return;}
    later(run,2600);
  }
  nxt(0);
}
run();

var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var main=root.querySelector('.trx2-tape-load-main');
var found=root.querySelector('.trx2-tape-load-found');
var fill=root.querySelector('.trx2-tape-load-fill');
var rest=root.querySelector('.trx2-tape-load-rest');
var cnt=root.querySelector('.trx2-tape-load-cnt');
var blk=root.querySelector('.trx2-tape-load-blk');
var N=24,t=[];
function pad(n,w){var s=''+n;while(s.length<w){s='0'+s;}return s;}
function bar(n){fill.textContent=new Array(n+1).join('█');rest.textContent=new Array(N-n+1).join('░');}
function later(f,m){t.push(setTimeout(f,m));}
if(rm){root.classList.remove('trx2-tape-load-idle');main.classList.remove('trx2-tape-load-bl');main.textContent='LOADING';found.textContent='FOUND ELITE';bar(17);cnt.textContent='106';blk.textContent='17';return;}
function load(n){
  bar(n);blk.textContent=pad(n,2);cnt.textContent=pad(4+n*6,3);
  if(n<N){later(function(){load(n+1);},150+Math.random()*90);return;}
  main.textContent='READY.';
  root.classList.add('trx2-tape-load-idle');
  later(run,1800);
}
function run(){
  for(var j=0;j<t.length;j++){clearTimeout(t[j]);}
  t=[];
  root.classList.add('trx2-tape-load-idle');
  main.classList.add('trx2-tape-load-bl');
  main.textContent='PRESS PLAY ON TAPE';found.textContent='';bar(0);cnt.textContent='000';blk.textContent='00';
  later(function(){
    root.classList.remove('trx2-tape-load-idle');
    main.classList.remove('trx2-tape-load-bl');
    main.textContent='SEARCHING FOR ELITE';
    later(function(){
      found.textContent='FOUND ELITE';
      later(function(){main.textContent='LOADING';load(0);},700);
    },900);
  },1500);
}
run();

