var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var band=root.querySelector('.trx2-zx-bars-band');
var st=root.querySelector('.trx2-zx-bars-st');
var by=root.querySelector('.trx2-zx-bars-by');
if(rm){st.textContent='Bytes';by.textContent='41056';band.classList.add('trx2-zx-bars-data');return;}
var tick=0,n=0,mode=0;
setInterval(function(){
  tick++;
  if(mode===0){
    if(tick>18){mode=1;tick=0;band.classList.add('trx2-zx-bars-data');st.textContent='Bytes';}
    return;
  }
  if(mode===1){
    n+=700+Math.floor(Math.random()*900);
    if(n>=41056){n=41056;mode=2;tick=0;band.classList.add('trx2-zx-bars-done');st.textContent='OK';}
    by.textContent=('00000'+n).slice(-5);
    return;
  }
  if(tick>14){mode=0;tick=0;n=0;band.classList.remove('trx2-zx-bars-data');band.classList.remove('trx2-zx-bars-done');st.textContent='Header';by.textContent='00000';}
},110);

var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var items=root.querySelectorAll('.trx2-a2-menu-it');
var sel=0,id=null;
function paint(){for(var i=0;i<items.length;i++){items[i].classList.toggle('trx2-a2-menu-sel',i===sel);}}
function adv(){sel=(sel+1)%items.length;paint();}
paint();
for(var i=0;i<items.length;i++){
  (function(k){items[k].addEventListener('mouseenter',function(){sel=k;paint();});})(i);
}
root.addEventListener('mouseenter',function(){if(id){clearInterval(id);id=null;}});
root.addEventListener('mouseleave',function(){if(!id&&!rm){id=setInterval(adv,1600);}});
if(!rm){id=setInterval(adv,1600);}

var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var strip=root.querySelector('.trx2-memmap-strip');
var scan=root.querySelector('.trx2-memmap-scan');
var map=[1,2,2,2,2,2,2,2,2,2,2,2,2,2,2,2,2,2,2,2,0,0,0,0,2,2,1,1,0,0,0,0];
var cells=[];
for(var i=0;i<32;i++){
  var s=document.createElement('span');
  s.className='trx2-memmap-c'+(map[i]===1?' trx2-memmap-c1':(map[i]===2?' trx2-memmap-c2':''));
  strip.appendChild(s);cells.push(s);
}
function hex(v){var h=v.toString(16).toUpperCase();while(h.length<4){h='0'+h;}return '$'+h;}
function show(i){for(var k=0;k<32;k++){cells[k].classList.toggle('trx2-memmap-hot',k===i);}scan.textContent=hex(i*2048);}
if(rm){show(13);return;}
var p=0;show(0);
setInterval(function(){p=(p+1)%32;show(p);},170);

