js:
var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var wrap=root.querySelector('.trx2-syspoke-wrap');
var out=root.querySelector('.trx2-syspoke-out');
var vs=[root.querySelector('.trx2-syspoke-v0'),root.querySelector('.trx2-syspoke-v1'),root.querySelector('.trx2-syspoke-v2')];
var ws=[root.querySelector('.trx2-syspoke-w0'),root.querySelector('.trx2-syspoke-w1'),root.querySelector('.trx2-syspoke-w2')];
var PAL=['#000000','#ffffff','#813338','#75cec8','#8e3c97','#56ac4d','#2e2c9b','#edf171','#8e5029','#553800','#c46c71','#4a4a4a','#7b7b7b','#a9ff9f','#706deb','#b2b2b2'];
var ROWS=6,txt=[],cur=[],buf=[];
for(var i=0;i<ROWS;i++){
  var d=document.createElement('div');d.className='trx2-syspoke-ln';
  var s=document.createElement('span');s.className='trx2-syspoke-tx';
  var c=document.createElement('span');c.className='trx2-syspoke-cu';
  d.appendChild(s);d.appendChild(c);out.appendChild(d);txt.push(s);cur.push(c);
}
function hx(v){var h=v.toString(16).toUpperCase();return h.length<2?'0'+h:h;}
function paint(a){for(var k=0;k<ROWS;k++){txt[k].textContent=buf[k]||'';cur[k].classList.toggle('trx2-syspoke-on',k===a);}}
function push(s){buf.push(s);if(buf.length>ROWS){buf.shift();}}
function setReg(r,v){vs[r].textContent=hx(v);ws[r].style.background=PAL[v];if(r===0){root.style.background=PAL[v];}if(r===1){wrap.style.background=PAL[v];}if(r===2){out.style.color=PAL[v];}}
function reset(){buf=['READY.'];setReg(0,14);setReg(1,6);setReg(2,14);paint(-1);}
reset();
if(rm){push('POKE 53280,0');push('READY.');push('SYS 49152');setReg(0,0);paint(-1);return;}
var seq=[['POKE 53280,0',0,0,''],['POKE 53281,11',1,11,''],['POKE 646,13',2,13,''],['SYS 49152',-1,0,'RASTER IRQ INSTALLED']];
var t=[];
function later(f,m){t.push(setTimeout(f,m));}
function typeLine(str,done){
  push('');var idx=buf.length-1,i=0;paint(idx);
  function tk(){
    if(i<str.length){i++;buf[idx]=str.slice(0,i);paint(idx);later(tk,52);return;}
    later(done,420);
  }
  tk();
}
function step(k){
  if(k>=seq.length){later(function(){reset();step(0);},2000);return;}
  var it=seq[k];
  typeLine(it[0],function(){
    if(it[1]>=0){setReg(it[1],it[2]);}
    if(it[3]){push(it[3]);}
    push('READY.');paint(-1);
    later(function(){step(k+1);},560);
  });
}
step(0);

var rm=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var rl=root.querySelector('.trx2-raster-rl');
var fr=root.querySelector('.trx2-raster-fr');
function h2(v){var s=v.toString(16).toUpperCase();return s.length<2?'0'+s:s;}
if(rm){rl.textContent='7B';fr.textContent='04096';return;}
var f=0,l=0;
setInterval(function(){
  f=(f+1)%100000;
  l=(l+37)%256;
  rl.textContent=h2(l);
  fr.textContent=('0000'+f).slice(-5);
},70);
